#!/usr/bin/env python3
"""
Script to fill in offer letter template with employee data
"""
import json
import re
from docx import Document

def replace_placeholders_in_paragraph(paragraph, data):
    """Replace placeholders in a paragraph's text"""
    full_text = paragraph.text

    # Replace all placeholders
    for key, value in data.items():
        placeholder = f"{{{{{key}}}}}"
        full_text = full_text.replace(placeholder, str(value))

    # Only update if text changed
    if full_text != paragraph.text:
        # Preserve formatting by replacing inline
        for run in paragraph.runs:
            for key, value in data.items():
                placeholder = f"{{{{{key}}}}}"
                if placeholder in run.text:
                    run.text = run.text.replace(placeholder, str(value))

def process_conditional_sections(doc, data):
    """Process conditional sections like {{IF_RELOCATION}}...{{END_IF_RELOCATION}}"""
    relocation = data.get('RELOCATION_PACKAGE', 'No')

    paragraphs_to_remove = []
    in_relocation_section = False
    relocation_paragraphs = []

    for i, paragraph in enumerate(doc.paragraphs):
        text = paragraph.text.strip()

        if '{{IF_RELOCATION}}' in text:
            in_relocation_section = True
            # Remove the IF marker from this paragraph
            paragraph.text = text.replace('{{IF_RELOCATION}}', '').strip()
            if relocation.lower() != 'yes' or not paragraph.text:
                paragraphs_to_remove.append(i)
            continue

        if '{{END_IF_RELOCATION}}' in text:
            in_relocation_section = False
            # Remove the END_IF marker from this paragraph
            paragraph.text = text.replace('{{END_IF_RELOCATION}}', '').strip()
            if relocation.lower() != 'yes' or not paragraph.text:
                paragraphs_to_remove.append(i)
            continue

        if in_relocation_section:
            if relocation.lower() != 'yes':
                paragraphs_to_remove.append(i)

    # Remove paragraphs in reverse order to maintain indices
    for idx in reversed(paragraphs_to_remove):
        p = doc.paragraphs[idx]
        p._element.getparent().remove(p._element)

def fill_template(template_path, data_path, output_path):
    """Fill offer letter template with employee data"""
    # Load employee data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    # Process conditional sections first
    process_conditional_sections(doc, data)

    # Replace placeholders in paragraphs
    for paragraph in doc.paragraphs:
        replace_placeholders_in_paragraph(paragraph, data)

    # Replace placeholders in tables (if any)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    replace_placeholders_in_paragraph(paragraph, data)

    # Replace placeholders in headers and footers
    for section in doc.sections:
        for header in [section.header, section.footer]:
            for paragraph in header.paragraphs:
                replace_placeholders_in_paragraph(paragraph, data)

    # Save filled document
    doc.save(output_path)
    print(f"Offer letter successfully created: {output_path}")

if __name__ == "__main__":
    fill_template(
        '/root/offer_letter_template.docx',
        '/root/employee_data.json',
        '/root/offer_letter_filled.docx'
    )

